            TohpeSearch(
                SamplingBudget(one_hot="all", sparse=8, dense=self.int_range(8, 40), sparse_max_weight=2),
                SourcePool(keep=6, reserve=1),
                z_choices=12,
            )
        )

    def _build_light_todd(self):
        return ToddSearch(
            SamplingBudget(one_hot=4, sparse=1, dense=0, sparse_max_weight=2),
            SourcePool(keep=self.int_range(2, 4), reserve=1),
            actions_per_bucket=1,
            buckets=ZBucketSearch(min_buckets=4, max_buckets=self.int_range(64, 256), limit_bucket=-1),
