        self.set_action_pool(ActionPool(final_size=self.int_range(20, 36)))
        self.set_tohpe_search(TohpeSearch(samples, SourcePool(keep=6, reserve=1), z_choices=8))
        self.set_todd_search(
            ToddSearch(
                SamplingBudget(one_hot=3, sparse=0, dense=0, sparse_max_weight=2),
                SourcePool(keep=12, reserve=6),
                actions_per_bucket=16,
                buckets=ZBucketSearch(min_buckets=128, max_buckets=6000, limit_bucket=-1),
            )
        )

    def __call__(self, params: Iterable[float]) -> float:
        values = np.asarray(self.run(params, SEEDS), dtype=float)
        return float(values.min() + 0.02 * values.std())


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        n = len(evaluator.extract_active())
        super().__init__(n_var=n, n_obj=1, xl=np.full(n, -1.5), xu=np.full(n, 1.5))
